---@param clipId_ string  @ 比如 "1"
---@param roleAnimator_ UnityEngine.Animator 
---@param timelineRootTF_ UnityEngine.Transform 
function IdolLive3D_TimeLineState:__init( clipId_, roleAnimator_, timelineRootTF_ )

    self.clipId = clipId_
    self.roleAnimator = roleAnimator_
    self.timelineRootTF = timelineRootTF_

    -- map: < k:markerName, v:{name,time} >
    self.markers = {
    }

    self.play = {
        duration = 0, -- clip 动画时长
        playTime = 0, -- 最后一次记录的 播放时间, 上一帧的 播放时间, [0,duration]
        startTime = 0,
        totalTime = 0, -- 开始播放本 clip 后, 不停累加的一个值, 可以大于 duration
        loopInteger = 0,   -- 播放时长 整数位
        loopDecimal = 0.0, -- 播放时长 小数位 [0,1]
    }

    -- 彻底隐藏另一个性别的根节点:
    local othNodeName = CfUtils.IsWoman() and IdolLive3D_States.timelineMaleName or IdolLive3D_States.timelineFemaleName
    IdolLive3D_Utils.TryShowOrHideByName( self.timelineRootTF, othNodeName, false )

    CfUtils.SetActive( self.timelineRootTF.gameObject, false ) -- 隐藏 timeline

    self.playableDirector = KTool.GetComponent(self.timelineRootTF.gameObject, typeof(PlayableDirector))
    assert( isNotNull(self.playableDirector) )
    self.playableDirector.playOnAwake = false
    if self.playableDirector.extrapolationMode == DirectorWrapMode.Hold then
        self.playableDirector.extrapolationMode = DirectorWrapMode.None -- 一遍播放结束后, time 会自动归零
    end 

    ---
    local vcamComps = self.timelineRootTF.gameObject:GetComponentsInChildren(typeof(CinemachineVirtualCamera),true) -- 包含自己
    if vcamComps.Length > 1 then 
        printError("koko - timeline 最多只能含有一个 vcam, 请检查")
        return
    end 
    ---@type Cinemachine.CinemachineVirtualCamera
    self.vcam = nil
    if vcamComps.Length > 0 and isNotNull(vcamComps[0]) then 
        self.vcam = vcamComps[0]
    end

    if isNotNull(self.vcam) then
        KTool.SetActive( self.vcam.gameObject, true )
        self.vcam.Priority = IdolLive3D_States.VCamPriority.Low
    end


    local timelineAsset = self.playableDirector.playableAsset
    ----
    local trackAssets = support.new_list(typeof(CS.UnityEngine.Timeline.TrackAsset))
    trackAssets:AddRange(timelineAsset:GetOutputTracks())


    local isBindTrackAnimator = false
    for i = 0, trackAssets.Count - 1 do
        local trackAsset = trackAssets[i]
        if isNotNull(trackAsset) then
            if string.lower(trackAsset.name) == "animator" then
                self.playableDirector:SetGenericBinding(trackAsset, self.roleAnimator)
                isBindTrackAnimator = true
            end
            
            -- markers:
            if string.lower(trackAsset.name) == "marker" then
                local markerNum = trackAsset:GetMarkerCount() 
                print("发现 marker 数量: " .. tostring(markerNum))
                for i=0, markerNum-1 do 
                    local marker = trackAsset:GetMarker(i)
                    if isNotNull(marker) then 
                        local markerName = string.lower(marker.name)
                        assert( IdolLive3D_Utils.IsKeyValid(markerName) )
                        print("-- i:"..tostring(i).."; time = " ..tostring(marker.time).."; name = " .. tostring(marker.name))
                        if self.markers[markerName] ~= nil then 
                            printError("发现 name 重复的 marker: " .. tostring(markerName))
                        end 
                        self.markers[markerName] = { name = markerName, time = marker.time }
                    end
                end
            end
            
        end
    end
    if isBindTrackAnimator ~= true then 
        printError("timeline track animator 绑定失败")
    end 

    ---
    self.isInit = true
end


-- 需外部调用 Delete()
function IdolLive3D_TimeLineState:__delete()

end


