function IdolLive3D_TimeLineState:BindFirstLoopStopCB( firstLoopStopCB_ )
    self.firstLoopStopCB = firstLoopStopCB_

    self.playableDirector:stopped( '+', function(playableDirector_)
        -- 需要在别处 完成 self:Hide() 的功能
        if self.firstLoopStopCB ~= nil then
            self.firstLoopStopCB(playableDirector_, self.clipId)
        end
    end)
end 


---@return Cinemachine.CinemachineVirtualCamera | nil
function IdolLive3D_TimeLineState:GetVCam()
    return self.vcam
end



function IdolLive3D_TimeLineState:Play()
    if self.isInit ~= true then 
        return
    end
    print("进入timeline")
    CfUtils.SetActive( self.timelineRootTF.gameObject, true ) -- 显示 timeline

    self.play = {
        duration = self.playableDirector.duration,
        playTime = 0,
        startTime = Time.time,
        totalTime = 0,
        loopInteger = 0,   -- 时长 整数位
        loopDecimal = 0.0, -- 时长 小数位
    }

    self.playableDirector:Play()     
end


function IdolLive3D_TimeLineState:Hide()
    if self.isInit ~= true then 
        printError("调用时机异常")
        return
    end 
    CfUtils.SetActive( self.timelineRootTF.gameObject, false )
end


---@return boolean
function IdolLive3D_TimeLineState:IsLoop()
    if self.isInit ~= true then 
        printError("调用时机异常")
        return false
    end 
    return self.playableDirector.extrapolationMode == CS.UnityEngine.Playables.DirectorWrapMode.Loop
end



-- 显示隐藏 "hideWhenNotPlay" 节点
-- function IdolLive3D_TimeLineState:_DoHideWhenNotPlay( isShow_ )
--     IdolLive3D_Utils.TryShowOrHideByName( self.timelineRootTF, IdolLive3D_States.hideWhenNotPlayName, isShow_ )
-- end 
 


function IdolLive3D_TimeLineState:PlayUpdate()
    if self.isInit ~= true then 
        printError("调用时机异常")
        return
    end 
    ---
    local playTime = self.playableDirector.time - self.playableDirector.initialTime -- 本值永远不会超过 duration
    ---
    self.play.loopDecimal = playTime / self.play.duration
    local lastFrameTime = self.play.playTime
    self.play.playTime = playTime
    self.play.totalTime = Time.time - self.play.startTime

    -- 当上一帧接近 0.99, 本帧接近 0.01 时, 意味着从本帧开始, 一次轮回结束了;
    if lastFrameTime > self.play.duration*0.9 and playTime < self.play.duration*0.1 then

        if self.playableDirector.extrapolationMode == DirectorWrapMode.Loop then
            if self.play.loopInteger == 0 then 
                -- 说明是第一次loop 的结束:
                if self.firstLoopStopCB ~= nil then
                    self.firstLoopStopCB(self.playableDirector, self.clipId)
                end
            end 
        end
        -- 本帧是一次循环的结束
        self.play.loopInteger = self.play.loopInteger + 1
    end 
    --printError( "int:" .. tostring(self.play.loopInteger) .. ", dec:" .. tostring(self.play.loopDecimal) )
    --printError("time:" .. tostring(self.playableDirector.time))
end






return IdolLive3D_TimeLineState
